sql.where:
lea.deleted_yn = 'N'

    AND lea.management_no ILIKE CONCAT('%', #{criteria.managementNo}, '%')


    AND personnel.name ILIKE CONCAT('%', #{criteria.teacherName}, '%')


    AND lea.management_item_code = #{criteria.managementItemCode}


    AND lea.occurred_date >= #{criteria.occurredDateFrom}


    AND lea.occurred_date <= #{criteria.occurredDateTo}


    AND lea.certification_status = #{criteria.certificationStatus}


    AND lea.teacher_user_id = #{criteria.viewerUserId}


    AND EXISTS (
        SELECT 1
        FROM organization_user_mappings scope_mapping
        WHERE scope_mapping.user_id = #{criteria.viewerUserId}
          AND scope_mapping.organization_code = lea.organization_code
          AND scope_mapping.status = 'ACTIVE'
    )
